"""Emit a Lean module that re-checks a PRISM problem and its certificates in the
Lean kernel.

Trust note (docs/TRUST_BOUNDARIES.md): this translator is part of the trusted
base for the *byte-to-model correspondence*: it maps the validated JSON problem to
Lean literals.  It performs no reasoning; all claims are re-derived by the Lean
kernel (`decide +kernel`) from the emitted data using the proved checkers.  The
emitted file also records the SHA-256 of the canonical problem encoding so that
the Lean artifact can be matched to the JSON artifact it was generated from.
"""
from __future__ import annotations

from fractions import Fraction
from typing import Dict, List, Optional

from .core import STOP, Problem, bits


def lean_rat(x: Fraction, nn: bool = False) -> str:
    x = Fraction(x)
    ty = "ℚ≥0" if nn else "ℚ"
    if x.denominator == 1:
        s = str(x.numerator)
    else:
        s = f"{x.numerator}/{x.denominator}"
    if x < 0:
        return f"(({s}) : {ty})"
    return f"({s} : {ty})"


def lean_finset(mask: int, n: int) -> str:
    idx = list(bits(mask))
    if len(idx) == n:
        return "Finset.univ"
    if not idx:
        return "∅"
    return "({" + ", ".join(str(i) for i in idx) + "} : Finset (Fin " + str(n) + "))"


def lean_policy(pol, r: int, indent: int = 4) -> str:
    if pol == STOP:
        return ".stop"
    subs = [lean_policy(pol["next"].get(o, STOP), r, indent + 2) for o in range(r)]
    return f"(.test {pol['e']} ![{', '.join(subs)}])"


def export(P: Problem, name: str, *, K_mask: Optional[int] = None, eps=Fraction(0),
           assumption_mask: Optional[int] = None, data: List = (), problem_hash: str = "",
           optimal: Optional[Dict] = None, impossible: Optional[tuple] = None,
           bounds: Optional[tuple] = None, countermodel: Optional[tuple] = None,
           doc: str = "") -> str:
    n, k = P.n, P.k
    r = max([1] + [len(o) for o in P.outcomes])
    eps = Fraction(eps)
    L = []
    L.append("module\n\npublic import PRISM.Certificates.Checker\n")
    L.append("/-!\n# Generated PRISM instance: " + name + "\n")
    if doc:
        L.append(doc + "\n")
    L.append(f"Problem SHA-256 (canonical JSON): `{problem_hash}`\n")
    L.append("Model index → identifier:\n")
    for m in range(n):
        L.append(f"* `{m}` ↦ `{P.models[m]}` (query {P.q[m]})")
    L.append("\nExperiment index → identifier (cost; outcomes):\n")
    for e in range(k):
        L.append(f"* `{e}` ↦ `{P.experiments[e]}` (cost {P.cost[e]}; " +
                 ", ".join(f"{i}=`{o}`" for i, o in enumerate(P.outcomes[e])) + ")")
    L.append("\nThis file is generated by `python/prism/lean_export.py`; do not edit.\n-/\n")
    L.append("@[expose] public section\n")
    L.append(f"namespace PRISM.Generated.{name}\n\nopen Problem\n")
    rows = ", ".join("![" + ", ".join(str(P.obs[m][e]) for e in range(k)) + "]" for m in range(n))
    L.append(f"/-- The problem data. -/\ndef P : Problem (Fin {n}) (Fin {k}) (Fin {r}) where")
    L.append(f"  obs := ![{rows}]")
    L.append("  q := ![" + ", ".join(lean_rat(x) for x in P.q) + "]")
    L.append("  cost := ![" + ", ".join(lean_rat(x, True) for x in P.cost) + "]\n")
    amask = P.full if assumption_mask is None else assumption_mask
    L.append("/-- Models satisfying the declared assumptions. -/")
    L.append(f"def A : Finset (Fin {n}) := {lean_finset(amask, n)}\n")
    L.append("/-- The observations (experiment, outcome). -/")
    L.append(f"def D : List (Fin {k} × Fin {r}) := [" + ", ".join(f"({e}, {o})" for e, o in data) + "]\n")
    L.append("/-- The version space `K(D, A)`, computed by the verified filter. -/")
    L.append(f"def K : Finset (Fin {n}) := P.versionSpace Finset.univ (· ∈ A) D\n")
    if K_mask is not None:
        L.append("/-- The version space is exactly the expected model set. -/")
        L.append(f"theorem K_eq : K = {lean_finset(K_mask, n)} := by decide +kernel\n")
    epsl = lean_rat(eps)
    if bounds is not None:
        lo, hi, mlo, mhi = bounds
        L.append("/-- Sharp query bounds with attaining admissible models. -/")
        L.append(f"theorem bounds_ok : P.checkBounds K {lean_rat(lo)} {lean_rat(hi)} {mlo} {mhi} = true := by\n  decide +kernel\n")
        L.append(f"theorem sharp_bounds : ∃ hK : K.Nonempty, P.lower K hK = {lean_rat(lo)} ∧ P.upper K hK = {lean_rat(hi)} :=\n  checkBounds_sound bounds_ok\n")
    if countermodel is not None:
        m, lean_pred, desc = countermodel
        L.append(f"/-- Countermodel: {desc} -/")
        L.append(f"theorem countermodel_ok : checkCountermodel K (fun m => {lean_pred}) {m} = true := by\n  decide +kernel\n")
    if impossible is not None:
        m1, m2 = impossible
        L.append("/-- Two-model impossibility certificate. -/")
        L.append(f"theorem impossible_ok : P.checkImpossible {epsl} K {m1} {m2} = true := by decide +kernel\n")
        L.append(f"theorem impossible : (∀ p : Policy (Fin {k}) (Fin {r}), ¬ P.Succeeds {epsl} p K) ∧ P.value {epsl} K = ⊤ :=\n  checkImpossible_sound (by norm_num) impossible_ok\n")
    if optimal is not None:
        adv = ", ".join(f"({lean_finset(S, n)}, {lean_rat(b, True)})" for S, b in optimal["adversary"])
        L.append("/-- Exact-optimality certificate (policy + core + adversary table). -/")
        L.append(f"def cert : OptCert (Fin {n}) (Fin {k}) (Fin {r}) where")
        L.append(f"  policy := {lean_policy(optimal['policy'], r)}")
        L.append(f"  bound := {lean_rat(optimal['bound'], True)}")
        L.append(f"  core := {lean_finset(optimal['core'], n)}")
        L.append(f"  adversary := [{adv}]\n")
        L.append("theorem cert_ok : P.checkOptimal " + epsl + " K cert = true := by decide +kernel\n")
        L.append("/-- The certified policy succeeds on every admissible model. -/")
        L.append(f"theorem policy_sound : P.Succeeds {epsl} cert.policy K :=\n  (checkOptimal_sound (by norm_num) cert_ok).1\n")
        L.append("/-- Its worst-case cost is exactly the certified bound. -/")
        L.append(f"theorem policy_cost : P.worstCost cert.policy K = {lean_rat(optimal['bound'], True)} :=\n  (checkOptimal_sound (by norm_num) cert_ok).2.1\n")
        L.append("/-- No successful adaptive policy is cheaper. -/")
        L.append(f"theorem policy_optimal : ∀ p : Policy (Fin {k}) (Fin {r}), P.Succeeds {epsl} p K →\n    {lean_rat(optimal['bound'], True)} ≤ P.worstCost p K :=\n  (checkOptimal_sound (by norm_num) cert_ok).2.2.1\n")
        L.append("/-- The exact Bellman value. -/")
        L.append(f"theorem value_eq : P.value {epsl} K = {lean_rat(optimal['bound'], True)} :=\n  (checkOptimal_sound (by norm_num) cert_ok).2.2.2\n")
    L.append(f"end PRISM.Generated.{name}\n")
    return "\n".join(L)
